#!/usr/bin/env python3
"""OS-9 native TSK tests against generated bytes and user's qnxprobe reader."""
import argparse
import datetime
import importlib.util
import io
import pathlib
import re
import subprocess
import tempfile
from os9_fixture import fixture


def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--tools',type=pathlib.Path,required=True)
    ap.add_argument('--reference',type=pathlib.Path,required=True)
    ap.add_argument('--real-image',type=pathlib.Path)
    opt=ap.parse_args()
    spec=importlib.util.spec_from_file_location('os9_reference',opt.reference/'qnxprobe.py')
    reference=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(reference)
    tools={n:opt.tools/n for n in ('fls','icat','fsstat','blkls','ils','istat')}
    def run(n,*args):return subprocess.check_output([str(tools[n]),*map(str,args)])
    def names(image,*args):
        out={}
        for line in run('fls','-r','-p',*args,image).decode().splitlines():
            m=re.match(r'\S+ (\d+):\t(.*)',line)
            if m:out[m[2]]=int(m[1])
        return out
    count=0
    with tempfile.TemporaryDirectory() as tmp:
        tmp=pathlib.Path(tmp)
        for bs in (128,256,512,1024,2048,4096):
            for cluster in (1,2,4):
                raw,expected,nodes,occupied=fixture(bs,cluster)
                image=tmp/'os9.img';image.write_bytes(raw)
                ref=reference.Os9RbfWalker(io.BytesIO(raw),0,len(raw))
                assert ref.sector_size==bs
                assert f'Block Size: {bs}'.encode() in run('fsstat',image)
                have=names(image)
                assert set(have)==set(expected)|{'sub'}
                assert 'deleted' not in have
                for name,data in expected.items():
                    assert have[name]==nodes[name]
                    assert run('icat',image,have[name])==data,name
                    assert b''.join(ref.read_file(nodes[name],len(data)))==data,name
                    count+=1
                free={int(l.split('|')[0]) for l in run('blkls','-l',image).decode().splitlines()[3:]}
                assert free==set(range(1024))-occupied
                assert b'OS9-FREE-MARKER' in run('blkls',image)
                stat=run('istat',image,nodes['f00.bin']).decode()
                assert 'UID: 4660' in stat and 'Links: 2' in stat and 'Mode: 604' in stat
                stamp=int(datetime.datetime(2026,10,12,19,55,tzinfo=datetime.timezone.utc).timestamp())
                assert f'Modified: {stamp}.' in stat
                assert 'Created: 1704153600.' in stat
                inode_list=run('ils','-a',image).decode()
                assert '\n4|a|' in inode_list
                prefix=tmp/'offset.img';prefix.write_bytes(bytes(8192)+raw)
                assert names(prefix,'-o',16)==have
                assert run('icat','-o',16,prefix,nodes['fragmented.bin'])==expected['fragmented.bin']
            # OS-9/68K relocated allocation-map field, with the same live tree.
            raw,expected,nodes,occupied=fixture(bs,4,True)
            image.write_bytes(raw)
            assert run('icat','-f','os9-rbf',image,nodes['fragmented.bin'])==expected['fragmented.bin']
            free={int(l.split('|')[0]) for l in run('blkls','-l',image).decode().splitlines()[3:]}
            assert free==set(range(1024))-occupied
            # False signatures, truncation, invalid root, bad extents and cycles.
            broken=tmp/'bad.img'
            variants=[bytes(4096),raw[:bs*3]]
            b=bytearray(raw);b[8:11]=b'\xff\xff\xff';variants.append(b)
            b=bytearray(raw);b[nodes['fragmented.bin']*bs+16:nodes['fragmented.bin']*bs+19]=b'\xff\xff\xff';variants.append(b)
            b=bytearray(raw);b[4*bs]&=127;variants.append(b)
            for bad in variants:
                broken.write_bytes(bad)
                result=subprocess.run([str(tools['fsstat']),'-f','os9',str(broken)],capture_output=True)
                assert result.returncode>0
            print(f'OS-9 sector size {bs}: cluster sizes 1/2/4, offsets, metadata, map relocation and malformed cases passed',flush=True)
    if opt.real_image:
        raw=opt.real_image.read_bytes()
        ref=reference.Os9RbfWalker(io.BytesIO(raw),0,len(raw))
        have=names(opt.real_image)
        wanted={}
        pending=[(ref.root,'')]
        visited=set()
        while pending:
            node,prefix=pending.pop()
            if node in visited:continue
            visited.add(node)
            for name,child in ref.listdir(node):
                path=prefix+name
                wanted[path]=child
                mode,size,_mtime=ref.entry(child)
                if mode & 0o170000==0o040000:pending.append((child,path+'/'))
                else:
                    data=b''.join(ref.read_file(child,size))
                    assert run('icat',opt.real_image,have[path])==data,path
                    count+=1
        assert have==wanted
        print(f'Historical Toolshed OS-9 disk: {len(wanted)} entries match the independent reference walk',flush=True)
    print(f'{count} OS-9 payload comparisons passed against generated bytes and Gerd1986/qnxprobe',flush=True)


if __name__=='__main__':main()
